INSERT INTO `short_script` (`script_id`, `episode_id`, `work_id`, `user_id`, `script_version`, `script_status`, `scene_json`, `estimated_total_sec`, `rhythm_json`, `total_score`, `force_ready_flag`) VALUES ('sp-dm-006-01', 'ep-dm-006-01', 'w-dm-006', 'u-demo-0001', 1, 'DRAFT', '[{"scene_no":1,"scene_location":"冲突现场","scene_summary":"替嫁进豪门的她，发现合同婚姻背后另有交易","line_list":[{"line_no":1,"character_name":"女主","line_text":"退婚书我签，但有个条件。","emotion":"COLD","estimated_sec":3},{"line_no":2,"character_name":"男主","line_text":"你凭什么跟我谈条件？","emotion":"ANGRY","estimated_sec":3}]},{"scene_no":2,"scene_location":"三年后","scene_summary":"女主带着资源回归。","line_list":[{"line_no":1,"character_name":"女主","line_text":"董事会，现在换我坐。","emotion":"CALM","estimated_sec":3},{"line_no":2,"character_name":"配角","line_text":"她怎么回来了？","emotion":"SHOCK","estimated_sec":2}]},{"scene_no":3,"scene_location":"对峙","scene_summary":"第1集的集末钩子。","line_list":[{"line_no":1,"character_name":"女主","line_text":"下一次，轮到你们求我。","emotion":"COLD","estimated_sec":3},{"line_no":2,"character_name":"男主","line_text":"等着瞧。","emotion":"TENSE","estimated_sec":2}]}]', 90, '{"beat_score":78,"hook_score":82,"pacing_note":"前紧后稳"}', 72, 0);
INSERT INTO `short_script_version` (`version_id`, `script_id`, `script_version`, `scene_json`, `total_score`, `change_summary`) VALUES ('sv-dm-006-01-1', 'sp-dm-006-01', 1, '[{"scene_no":1,"scene_location":"冲突现场","scene_summary":"替嫁进豪门的她，发现合同婚姻背后另有交易","line_list":[{"line_no":1,"character_name":"女主","line_text":"退婚书我签，但有个条件。","emotion":"COLD","estimated_sec":3},{"line_no":2,"character_name":"男主","line_text":"你凭什么跟我谈条件？","emotion":"ANGRY","estimated_sec":3}]},{"scene_no":2,"scene_location":"三年后","scene_summary":"女主带着资源回归。","line_list":[{"line_no":1,"character_name":"女主","line_text":"董事会，现在换我坐。","emotion":"CALM","estimated_sec":3},{"line_no":2,"character_name":"配角","line_text":"她怎么回来了？","emotion":"SHOCK","estimated_sec":2}]},{"scene_no":3,"scene_location":"对峙","scene_summary":"第1集的集末钩子。","line_list":[{"line_no":1,"character_name":"女主","line_text":"下一次，轮到你们求我。","emotion":"COLD","estimated_sec":3},{"line_no":2,"character_name":"男主","line_text":"等着瞧。","emotion":"TENSE","estimated_sec":2}]}]', 70, '初稿');
